"""Design evaluation and optimisation for the A2 lateral package."""
import math, itertools, json, sys
import numpy as np
from a2 import *

W_CACHE = wcache()

# exact zone areas (roof outline minus opening), by cell integration at L3 (exact for this geometry)
def zone_areas():
    m = Mesh(OUTLINE, OPENINGS, 2.5, bbox=(0.0, 0.0, 240.0, 180.0))
    A = {}
    for cx, cy in zip(m.cx, m.cy):
        for z, (x0, y0, x1, y1) in ZONES.items():
            if x0 < cx < x1 and y0 < cy < y1:
                A[z] = A.get(z, 0.0) + 2.5 ** 2
    return A


ZONE_AREA = zone_areas()
CHORD_LEN = {k: math.hypot(b[0] - a[0], b[1] - a[1]) for k, (a, b) in CHORD_LINES.items()}


def panel_weight(mk):
    p = PANELS[mk]
    return GAMMA_C * p['L'] * p['top'] * p['t'] / 12.0  # kips, gross


def panel_checks(Vmax):
    """Vmax: dict panel -> max |V| (kips, ASD). Returns embeds, tiedown, flags."""
    out = {}
    for mk in PANEL_ORDER:
        p = PANELS[mk]
        V = Vmax.get(mk, 0.0)
        n_sp = max(2, math.ceil(p['L'] / E1_SPACING - 1e-9))
        n_v = math.ceil(V / E1_CAP - 1e-9) if V > 0 else 0
        n = max(n_sp, n_v)
        Wt = panel_weight(mk)
        MR = 0.6 * Wt * p['L'] / 2.0
        MOT = V * HDECK
        td = MOT > MR
        MR_td = MR + T1_CAP * p['L']
        out[mk] = dict(V=V, n_sp=n_sp, n_v=n_v, embeds=n, W=Wt, MR=MR, MOT=MOT, tiedown=td,
                       MR_td=MR_td, stab_ok=(MOT <= (MR_td if td else MR)),
                       B1=B1_CAP * p['L'], B1_ok=(V <= B1_CAP * p['L']))
    return out


def analyse(deck, chord, H=5.0, conv='E2+x', scenarios=None):
    kw = {}
    if conv == 'E2-x':
        kw['e2_inward'] = (-1.0, 0.0)
    M = A2Model(H, deck, chord, **kw)
    sc = scenarios or SC_ORDER
    R = {s: M.run(s, W_CACHE) for s in sc}
    return M, R


def summarize(deck, chord, R, margins=None):
    mg = dict(deck=1.0, chord=1.0, drift=1.0, b1=1.0, embed=1.0, td=1.0)
    if margins:
        mg.update(margins)
    S = {}
    S['zone_dem'] = {z: max(R[s]['zone_max'][z] for s in R) for z in ZONE_ORDER}
    S['drift'] = {a: max(R[s]['drift'][a] for s in R) for a in ('X', 'Y')}
    S['chord_T'] = {c: max(R[s]['chord_T'][c] for s in R) for c in CHORD_ORDER}
    S['chord_C'] = {c: max(R[s]['chord_C'][c] for s in R) for c in CHORD_ORDER}
    pv = {}
    for s in R:
        acc = {}
        for pid, v in R[s]['pier_force'].items():
            mk = pid.rsplit('-P', 1)[0]
            acc[mk] = acc.get(mk, 0.0) + v
        for mk, v in acc.items():
            pv[mk] = max(pv.get(mk, 0.0), abs(v))
    S['panel_V'] = pv
    S['pier_drift'] = max(abs(v) for s in R for v in R[s]['pier_disp_in'].values())
    viol = []
    for z in ZONE_ORDER:
        if S['zone_dem'][z] * mg['deck'] > DECK[deck[z]]['cap']:
            viol.append(('deck', z, S['zone_dem'][z] * mg['deck'] / DECK[deck[z]]['cap']))
    for a in ('X', 'Y'):
        if S['drift'][a] * mg['drift'] > DEFL_LIMIT:
            viol.append(('drift', a, S['drift'][a] * mg['drift'] / DEFL_LIMIT))
    for c in CHORD_ORDER:
        sec = CHORD[chord[c]]
        r = max(S['chord_T'][c] / sec['T'], S['chord_C'][c] / sec['C']) * mg['chord']
        if r > 1.0:
            viol.append(('chord', c, r))
    pvm = {k: v * mg['b1'] for k, v in pv.items()}
    for mk, v in pvm.items():
        if v > B1_CAP * PANELS[mk]['L']:
            viol.append(('b1', mk, v / (B1_CAP * PANELS[mk]['L'])))
    if S['pier_drift'] > HDECK * 12 / 400.0:
        viol.append(('pierdrift', '', S['pier_drift'] / (HDECK * 12 / 400.0)))
    types = set(deck.values())
    if len(types) > MAX_DECK_TYPES:
        viol.append(('types', '', len(types)))
    # connections with margins
    pc = panel_checks({k: v * mg['embed'] for k, v in pv.items()})
    pc_td = panel_checks({k: v * mg['td'] for k, v in pv.items()})
    for mk in pc:
        pc[mk]['tiedown'] = pc_td[mk]['tiedown']
        if not pc_td[mk]['stab_ok']:
            viol.append(('stab', mk, pc_td[mk]['MOT'] / pc_td[mk]['MR_td']))
    S['panels'] = pc
    cost = {}
    cost['deck'] = sum(ZONE_AREA[z] * DECK[deck[z]]['cost'] for z in ZONE_ORDER)
    cost['chord'] = sum(CHORD_LEN[c] * CHORD[chord[c]]['wplf'] * STEEL_RATE for c in CHORD_ORDER)
    cost['embeds'] = sum(pc[mk]['embeds'] for mk in pc) * E1_COST
    cost['tiedowns'] = sum(1 for mk in pc if pc[mk]['tiedown']) * T1_COST
    cost['total'] = sum(cost.values())
    if cost['total'] > COST_CAP:
        viol.append(('cost', '', cost['total'] / COST_CAP))
    S['cost'] = cost
    S['viol'] = viol
    S['feasible'] = len(viol) == 0
    return S


def merge_S(Slist):
    """Envelope of several summaries (for robustness across conventions)."""
    S = dict(Slist[0])
    S['zone_dem'] = {z: max(s['zone_dem'][z] for s in Slist) for z in ZONE_ORDER}
    S['drift'] = {a: max(s['drift'][a] for s in Slist) for a in ('X', 'Y')}
    S['chord_T'] = {c: max(s['chord_T'][c] for s in Slist) for c in CHORD_ORDER}
    S['chord_C'] = {c: max(s['chord_C'][c] for s in Slist) for c in CHORD_ORDER}
    S['panel_V'] = {k: max(s['panel_V'].get(k, 0) for s in Slist) for k in Slist[0]['panel_V']}
    return S

