"""Local search optimiser with margins and pair moves."""
import sys, json, time, random
from opt import *

MG = dict(deck=1.01, chord=1.01, drift=1.012, b1=1.012, embed=1.02, td=1.025)


def ev(deck, chord, convs):
    return evaluate(deck, chord, convs, MG)


def feasible_cost(S):
    return S['cost']['total'] if S['feasible'] else None


def single_moves(deck, chord):
    mv = []
    for z in ZONE_ORDER:
        for d in DECK_BY_COST:
            if d != deck[z]:
                mv.append(('deck', z, d))
    for c in CHORD_ORDER:
        for s in SEC_BY_W:
            if s != chord[c]:
                mv.append(('chord', c, s))
    return mv


def apply(deck, chord, mv):
    d2, c2 = dict(deck), dict(chord)
    for kind, item, new in mv:
        if kind == 'deck':
            d2[item] = new
        else:
            c2[item] = new
    return d2, c2


def est_delta(deck, chord, mv):
    dc = 0.0
    for kind, item, new in mv:
        if kind == 'deck':
            dc += ZONE_AREA[item] * (DECK[new]['cost'] - DECK[deck[item]]['cost'])
        else:
            dc += CHORD_LEN[item] * STEEL_RATE * (CHORD[new]['wplf'] - CHORD[chord[item]]['wplf'])
    return dc


def descend(deck, chord, convs, t_end, log=print, pair_tries=400, seed=0):
    rnd = random.Random(seed)
    S = ev(deck, chord, convs)
    assert S['feasible'], S['viol']
    cost = S['cost']['total']
    while time.time() < t_end:
        improved = False
        # single moves sorted by estimated saving
        mvs = single_moves(deck, chord)
        mvs.sort(key=lambda m: est_delta(deck, chord, [m]))
        for m in mvs:
            if time.time() > t_end:
                break
            d2, c2 = apply(deck, chord, [m])
            if len(set(d2.values())) > MAX_DECK_TYPES:
                continue
            if est_delta(deck, chord, [m]) > 3 * T1_COST:
                continue
            S2 = ev(d2, c2, convs)
            if S2['feasible'] and S2['cost']['total'] < cost - 0.01:
                log('single %s : %.0f -> %.0f' % (m, cost, S2['cost']['total']))
                deck, chord, S, cost = d2, c2, S2, S2['cost']['total']
                improved = True
                break
        if improved:
            continue
        # pair moves: one cheaper + one dearer
        down = [m for m in single_moves(deck, chord) if est_delta(deck, chord, [m]) < 0]
        up = [m for m in single_moves(deck, chord) if est_delta(deck, chord, [m]) > 0]
        tried = 0
        while tried < pair_tries and time.time() < t_end:
            a = rnd.choice(down)
            b = rnd.choice(up)
            if a[1] == b[1]:
                continue
            mv = [a, b]
            de = est_delta(deck, chord, mv)
            if de > 2 * T1_COST:
                continue
            d2, c2 = apply(deck, chord, mv)
            if len(set(d2.values())) > MAX_DECK_TYPES:
                continue
            tried += 1
            S2 = ev(d2, c2, convs)
            if S2['feasible'] and S2['cost']['total'] < cost - 0.01:
                log('pair %s : %.0f -> %.0f' % (mv, cost, S2['cost']['total']))
                deck, chord, S, cost = d2, c2, S2, S2['cost']['total']
                improved = True
                break
        if not improved:
            log('no improvement found in pair sample')
            break
    return deck, chord, S


def make_feasible(deck, chord, convs, log=print):
    for it in range(200):
        S = ev(deck, chord, convs)
        if S['feasible']:
            return deck, chord, S
        if fix_simple(deck, chord, S, MG):
            continue
        base_v = viol_measure(S); base_c = S['cost']['total']
        best = None
        moves = []
        for z in ZONE_ORDER:
            nd = next_up_deck(deck[z])
            if nd: moves.append(('deck', z, nd))
        for c in CHORD_ORDER:
            ns = next_up_sec(chord[c])
            if ns: moves.append(('chord', c, ns))
        for m in moves:
            d2, c2 = apply(deck, chord, [m])
            if len(set(d2.values())) > MAX_DECK_TYPES:
                continue
            S2 = ev(d2, c2, convs)
            dv = base_v - viol_measure(S2)
            dc = max(S2['cost']['total'] - base_c, 1.0)
            if best is None or dv / dc > best[0]:
                best = (dv / dc, m, dv)
        if best is None or best[2] <= 0:
            log('stuck making feasible', S['viol'])
            return deck, chord, S
        deck, chord = apply(deck, chord, [best[1]])
    return deck, chord, ev(deck, chord, convs)


if __name__ == '__main__':
    convs = tuple(sys.argv[1].split(','))
    tl = float(sys.argv[2])
    tag = sys.argv[3]
    start = sys.argv[4] if len(sys.argv) > 4 else None
    t0 = time.time()
    if start:
        b = json.load(open(start))
        deck, chord = b['deck'], b['chord']
    else:
        deck = {z: 'D22-36/4-4' for z in ZONE_ORDER}
        chord = {c: 'PL3x3/8' for c in CHORD_ORDER}
        chord['C-E2'] = 'PL12x1'
    deck, chord, S = make_feasible(deck, chord, convs)
    print('start feasible', S['feasible'], S['cost']['total'], time.time() - t0, flush=True)
    best = None
    seed = 0
    while time.time() - t0 < tl:
        deck, chord, S = descend(deck, chord, convs, t0 + tl, log=lambda s: print(s, flush=True), seed=seed)
        if best is None or S['cost']['total'] < best[0]:
            best = (S['cost']['total'], dict(deck), dict(chord))
            json.dump(dict(deck=deck, chord=chord, cost=S['cost']), open('best_%s.json' % tag, 'w'), indent=1)
        print('descent done', S['cost']['total'], time.time() - t0, flush=True)
        seed += 1
        # perturb: random upgrade of two zones then re-descend
        rnd = random.Random(seed)
        for _ in range(2):
            z = rnd.choice(ZONE_ORDER)
            nd = next_up_deck(deck[z])
            if nd and len(set(list(deck.values()) + [nd])) <= MAX_DECK_TYPES:
                deck[z] = nd
        deck, chord, S = make_feasible(deck, chord, convs, log=lambda *a: None)
        if not S['feasible']:
            deck, chord = dict(best[1]), dict(best[2])
    print('BEST', best[0], best[1], best[2])

