"""Systematic pair search from a feasible design (envelope of both conventions, margins)."""
import sys, json, time, itertools
from opt2 import *

convs = ('E2+x', 'E2-x')


def steps(lst, cur, k):
    i = lst.index(cur)
    return [lst[j] for j in range(max(0, i - k), min(len(lst), i + k + 1)) if j != i]


def neighbours(deck, chord):
    down, up = [], []
    for z in ZONE_ORDER:
        for d in DECK_BY_COST:
            if d == deck[z]:
                continue
            m = ('deck', z, d)
            (down if DECK[d]['cost'] < DECK[deck[z]]['cost'] else up).append(m)
    for c in CHORD_ORDER:
        for s in steps(SEC_BY_W, chord[c], 4):
            m = ('chord', c, s)
            (down if CHORD[s]['wplf'] < CHORD[chord[c]]['wplf'] else up).append(m)
    return down, up


def run(deck, chord, t_end, tag):
    S = ev(deck, chord, convs)
    assert S['feasible']
    cost = S['cost']['total']
    while time.time() < t_end:
        down, up = neighbours(deck, chord)
        # candidate pairs with an estimated net saving (or small increase that might drop a tie-down)
        cands = []
        for a in down:
            for b in up:
                if a[1] == b[1]:
                    continue
                de = est_delta(deck, chord, [a, b])
                if de < 0:
                    cands.append((de, [a, b]))
        for a in down:
            de = est_delta(deck, chord, [a])
            cands.append((de, [a]))
        cands.sort(key=lambda t: t[0])
        print('candidates', len(cands), flush=True)
        improved = False
        for de, mv in cands:
            if time.time() > t_end:
                break
            d2, c2 = apply(deck, chord, mv)
            if len(set(d2.values())) > MAX_DECK_TYPES:
                continue
            S2 = ev(d2, c2, convs)
            if S2['feasible'] and S2['cost']['total'] < cost - 0.01:
                print('improve %s : %.0f -> %.0f' % (mv, cost, S2['cost']['total']), flush=True)
                deck, chord, S, cost = d2, c2, S2, S2['cost']['total']
                json.dump(dict(deck=deck, chord=chord, cost=S['cost']), open('best_%s.json' % tag, 'w'), indent=1)
                improved = True
                break
        if not improved:
            print('pair-optimal', cost, flush=True)
            break
    return deck, chord, S


if __name__ == '__main__':
    b = json.load(open(sys.argv[1]))
    tl = float(sys.argv[2])
    tag = sys.argv[3]
    deck, chord, S = run(b['deck'], b['chord'], time.time() + tl, tag)
    print('FINAL', S['cost']['total'], deck, chord)
